ANALYZE ess_mcv_correlated;
SELECT 'METAEXT|' || 'correlated__ab_cd__target300' || '|' || 1::text || '|' || e.stxname || '|' || e.oid::text || '|' || e.stxstattarget::text || '|' || (d.stxdmcv IS NOT NULL)::text FROM pg_statistic_ext e LEFT JOIN pg_statistic_ext_data d ON d.stxoid=e.oid WHERE e.stxrelid='ess_mcv_correlated'::regclass AND e.stxname IN ('ess_mcv_correlated_ab', 'ess_mcv_correlated_bc', 'ess_mcv_correlated_cd') ORDER BY e.stxname;
SELECT 'METAEXT|' || 'correlated__ab_cd__target300' || '|' || 1::text || '|NONE' WHERE NOT EXISTS (SELECT 1 FROM pg_statistic_ext e WHERE e.stxrelid='ess_mcv_correlated'::regclass AND e.stxname IN ('ess_mcv_correlated_ab', 'ess_mcv_correlated_bc', 'ess_mcv_correlated_cd'));
SELECT 'METAORD|' || 'correlated__ab_cd__target300' || '|' || 1::text || '|' || c.oid::text || '|' || string_agg(a.attname || '=' || a.attstattarget::text, ',' ORDER BY a.attnum) FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid WHERE c.oid='ess_mcv_correlated'::regclass AND a.attnum>0 AND NOT a.attisdropped GROUP BY c.oid;
